mapper.select:
select distinct
    oa.id as id,
    oa.open_id as openId,
    oa.org_id as orgId,
    oa.dentist_id as dentistId,
    oa.patient_id as patientId,
    oa.appoint_item_id as appointItemId,
    oaitem.name as appointItemName,
    oa.appoint_content as appointContent,
    date_format(oa.appoint_date,'%Y-%m-%d') as appointDate,
    date_format(oa.appoint_time,'%H:%i') as appointTime,
    oaitem.duration as duration,
    oa.patient_name as patientName,
    oa.patient_phone as patientPhone,
    oa.status as status,
    date_format(oa.crt_time,'%Y-%m-%d') as crtTime,
    a.id as appointmentId,
    a.confirm_status as confirmStatus
from online_appointment oa left join online_appoint_item oaitem on oaitem.item_id = oa.appoint_item_id LEFT join appointment a on a.online_appointment_id = oa.id and oa.patient_id = a.patient_id and a.inservice = true


        and oa.org_id = #{query.orgId}


        and oa.open_id = #{query.openId}


        and oa.dentist_id = #{query.dentistId}


        and oa.patient_id = #{query.patientId}


        and date_format(oa.appoint_date,'%Y-%m-%d') >= #{query.appointStartDate}


        and date_format(oa.appoint_date,'%Y-%m-%d') <= #{query.appointEndDate}


        and oa.patient_name like concat('%',#{query.patientName},'%')


        and oa.patient_phone = #{query.phone}


        and oa.status = #{query.status}


        and oa.inservice = #{query.inservice}


        and a.confirm_status = #{query.confirmStatus}



    order by oa.id desc
